@section('js')
<script>
document.addEventListener('DOMContentLoaded', function () {
    var csrf = document.querySelector('meta[name="csrf-token"]').content;
    var previewUrl = @json(route('admin.moodle-sync.preview'));
    var startUrl = @json(route('admin.moodle-sync.start'));
    var testUrl = @json(route('admin.moodle-sync.test'));
    var progressUrl = @json(route('admin.moodle-sync.progress', ['run' => '__RUN__']));
    var labels = {users:'User', cohorts:'Kohor', categories:'Kategori', all:'Semua domain'};
    var fmt = function (value) { return new Intl.NumberFormat('id-ID').format(value || 0); };
    var notify = function (type, message) { if (window.toastr && typeof window.toastr[type] === 'function') window.toastr[type](message); else window.alert(message); };
    var post = function (url, body) { return fetch(url, {method:'POST', headers:{'Content-Type':'application/json', 'Accept':'application/json', 'X-CSRF-TOKEN':csrf}, body:JSON.stringify(body || {})}).then(function (response) { return response.json().then(function (data) { if (!response.ok) throw new Error(data.message || 'Permintaan gagal.'); return data; }); }); };
    var modal = function (options) { return window.Swal ? window.Swal.fire(options) : Promise.resolve({isConfirmed:window.confirm(options.text || options.title || 'Lanjutkan?')}); };
    var progressHtml = function (stage, percent, log) { return '<div class="live-stage mb-2">'+stage+'</div><div class="progress mb-2"><div class="progress-bar" style="width:'+percent+'%">'+percent+'%</div></div><div class="live-count small text-muted">0 item</div><div class="live-log mt-3">['+percent+'%] '+log+'</div>'; };
    var updateProgress = function (data) { var box = window.Swal && window.Swal.getHtmlContainer ? window.Swal.getHtmlContainer() : null; if (!box) return; var bar=box.querySelector('.progress-bar'), stage=box.querySelector('.live-stage'), count=box.querySelector('.live-count'), log=box.querySelector('.live-log'); if(bar){bar.style.width=data.percent+'%';bar.textContent=data.percent+'%';} if(stage)stage.textContent=data.stage || 'Memproses'; if(count)count.textContent=fmt(data.processed)+' / '+fmt(data.total)+' item'; if(log)log.innerHTML='['+data.percent+'%] '+(data.stage || 'Memproses')+'<br>'+log.innerHTML; };
    var watchRun = function (runId) { fetch(progressUrl.replace('__RUN__', runId), {headers:{'Accept':'application/json'}}).then(function (response) { return response.json(); }).then(function (data) { updateProgress(data); if (data.status === 'success' || data.status === 'failed') { if(window.Swal) window.Swal.close(); notify(data.status === 'success' ? 'success' : 'error', data.status === 'success' ? 'Smart Check selesai.' : (data.error || 'Proses gagal.')); setTimeout(function(){location.reload();}, 700); } else setTimeout(function(){watchRun(runId);}, 1200); }).catch(function(){setTimeout(function(){watchRun(runId);}, 2500);}); };
    var beginRun = function (type, token) { post(startUrl, {type:type, preview_token:token, confirmed:true}).then(function (data) { if(window.Swal) window.Swal.fire({title:'Proses berjalan', html:progressHtml('Menunggu worker', 0, 'Perubahan masuk antrean'), allowOutsideClick:false, showConfirmButton:false}); watchRun(data.run_id); }).catch(function(error){notify('error', error.message);}); };
    var renderUserRows = function (items) { return items.map(function (item) { var status = item.status === 'missing' ? 'Belum ada' : (item.status === 'different' ? 'Data berbeda' : 'Sesuai'); return '<tr><td>'+item.type+'</td><td><code>'+item.identifier+'</code></td><td>'+item.local_name+'</td><td>'+(item.moodle_name || '<em>Belum ada</em>')+'</td><td>'+status+'</td></tr>'; }).join(''); };
    var renderCohortRows = function (items) { return Object.keys(items).map(function (key) { var item=items[key]; var status=item.metadata_action==='create'?'Buat':(item.metadata_action==='update'?'Perbarui':'Sama'); return '<tr><td>'+item.idnumber+'</td><td>'+item.local_name+'</td><td>'+(item.moodle_name || '<em>Belum ada</em>')+'</td><td>'+status+'</td><td>'+fmt(item.local_members)+' / '+fmt(item.moodle_members)+'</td><td>'+fmt(item.membership_add)+'</td></tr>'; }).join(''); };
    var showPreview = function (type, data) { var actions=data.actions, preview=data.preview, users=(data.plan.users && data.plan.users.details) || [], cohorts=(data.plan.cohorts && data.plan.cohorts.details) || {}; var table=''; if(type === 'users') table='<div class="table-responsive mt-3" style="max-height:300px"><table class="table table-sm text-left"><thead><tr><th>Jenis</th><th>NISN/NIK</th><th>Nama SIMANSA</th><th>Nama Moodle</th><th>Status</th></tr></thead><tbody>'+renderUserRows(users)+'</tbody></table></div>'; if(type === 'cohorts') table='<div class="table-responsive mt-3" style="max-height:300px"><table class="table table-sm text-left"><thead><tr><th>ID</th><th>SIMANSA</th><th>Moodle</th><th>Status</th><th>Anggota S/M</th><th>Masuk</th></tr></thead><tbody>'+renderCohortRows(cohorts)+'</tbody></table></div>'; var html='<div class="row text-center"><div class="col-6"><strong class="d-block h4">'+fmt(preview.students)+'</strong><small>Siswa aktif ber-rombel</small></div><div class="col-6"><strong class="d-block h4">'+fmt(preview.gtk)+'</strong><small>GTK aktif</small></div></div><div class="alert alert-warning mt-3 text-left"><b>Rencana perubahan</b><br>Buat: <strong>'+fmt(actions.create)+'</strong> · Perbarui: <strong>'+fmt(actions.update)+'</strong> · Anggota masuk: <strong>'+fmt(actions.membership_add)+'</strong> · Anggota keluar: <strong>'+fmt(actions.membership_remove)+'</strong><br>Tidak berubah: <strong>'+fmt(actions.unchanged)+'</strong><br><small>Ini masih preview. Moodle belum diubah.</small></div>'+table; return modal({icon:'info', title:'Smart Check '+labels[type], html:html, showCancelButton:true, confirmButtonText:'Lanjutkan', cancelButtonText:'Batal'}); };
    var confirmRun = function (type, data) { if(!data.comparison_complete){notify('error','Perbandingan belum lengkap.');return;} var html='<div class="text-left"><p>Periksa kembali rencana Smart Check sebelum menulis ke Moodle.</p><label><input id="moodle-confirm-checkbox" type="checkbox" style="margin-right:8px"> Saya menyetujui perubahan yang tampil pada preview.</label></div>'; modal({icon:'warning', title:'Konfirmasi perubahan', html:html, showCancelButton:true, confirmButtonText:'Ya, mulai', cancelButtonText:'Batal', focusConfirm:false, didOpen:function(){var button=window.Swal.getConfirmButton();button.disabled=true;document.getElementById('moodle-confirm-checkbox').onchange=function(){button.disabled=!this.checked;};}, preConfirm:function(){if(!document.getElementById('moodle-confirm-checkbox').checked){window.Swal.showValidationMessage('Persetujuan wajib dicentang.');return false;}return true;}}).then(function(result){if(result.isConfirmed)beginRun(type,data.preview_token);}); };
    document.getElementById('moodle-test-connection').addEventListener('click', function () { modal({icon:'question', title:'Tes koneksi Moodle?', text:'Tes ini hanya membaca informasi situs.', showCancelButton:true, confirmButtonText:'Ya, tes koneksi', cancelButtonText:'Batal'}).then(function(result){if(!result.isConfirmed)return;if(window.Swal)window.Swal.fire({title:'Menguji koneksi',html:progressHtml('Web Service Moodle',25,'Permintaan dikirim'),allowOutsideClick:false,showConfirmButton:false});post(testUrl).then(function(data){modal({icon:'success',title:'Koneksi berhasil',text:data.message,confirmButtonText:'Tutup'});}).catch(function(error){modal({icon:'error',title:'Koneksi gagal',text:error.message});});}); });
    document.querySelectorAll('.sync-preview').forEach(function (button) { button.addEventListener('click', function () { var type=button.dataset.type; if(window.Swal)window.Swal.fire({title:'Membandingkan '+labels[type],html:progressHtml('Membaca SIMANSA dan Moodle',10,'Smart Check read-only'),allowOutsideClick:false,showConfirmButton:false}); post(previewUrl,{type:type}).then(function(data){return showPreview(type,data).then(function(result){if(result.isConfirmed)confirmRun(type,data);});}).catch(function(error){modal({icon:'error',title:'Smart Check gagal',text:error.message});}); }); });
});
</script>
@endsection
